SELECT jsonb_build_object('effects',count(*),'actual_sh004_result_and_source_match',coalesce(bool_and(e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id AND e.operation=q.operation AND e.subject_scope=q.subject_scope AND e.semantic_effect_key=q.semantic_key AND e.fingerprint=q.fingerprint AND e.state='committed' AND e.source_revision=q.source_revision AND e.fence=0 AND e.result_schema_id=q.result_schema_id AND e.result_schema_id='SH-004.v1#/$defs/response' AND e.result_hash=q.result_digest AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex') AND e.mutation_transaction_id=q.mutation_transaction_id AND e.committed_at>=q.created_at AND e.committed_at<=clock_timestamp()),false)) FROM platform.runtime_effect_receipt e JOIN platform.runtime_command_receipt q ON q.id=e.command_receipt_id WHERE e.id='67833833-d7ef-5d87-a1d7-cc5940c6e420';
